head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > getVoidXML]<br/>Row 의 상태가 '삽입 후 삭제' 또는 '제거' 인 Row 데이터를 XML 객체로 반환합니다.",
    "validation" : [
        "필터와 정렬이 적용된 상태를 기준으로 Row 상태값이 'V', 'E' 인 Row 데이터가 반환됩니다.",
        "onlyVoid(선택) 파라미터로 Row 상태값이 'E' 인 '제거' Row 의 데이터를 포함할지 true/false 로 설정합니다.",
        "onlyVoid(선택) 파라미터로 true 설정 시 Row 상태값이 'E' 인 Row 데이터를 반환값에 포함하지 않습니다.",
        "onlyVoid(선택) 파라미터로 미설정 또는 false 설정 시 Row 상태값이 'E' 인 Row 데이터를 반환값에 포함합니다.",
        "반환값으로 필터와 정렬이 적용된 상태를 기준으로 Row 상태가 '삭제' 또는 '제거' 인 데이터를 XML 객체로 반환합니다.",
        "Row 의 상태값이 'V', 'E' 인 Row 가 반환되며, onlyVoid 파라미터값이 false 이면 'E' 상태의 Row 데이터는 포함되지 않습니다.",
        "XML 은 정렬이 적용된 순서대로 생성되며 'E' 상태인 Row 는 필터링/정렬 여부와 관계없이 마지막에 생성됩니다.",
        "DataList 모듈에 필터가 적용되지 않은 경우 전체 Row 데이터를 기준으로 처리됩니다.",
        "반환된 객체의 xml 속성값은 baseNode 속성값이 최상위 태그명으로 적용되고, 반복되는 데이터 태그엔 repeatNode 속성값이 적용됩니다.",
        "데이터 태그는 index 속성으로 Row 의 인덱스값이 설정되며, 'E' 상태인 Row 는 'removed' 값이 설정됩니다.",
        "데이터 태그는 DataList 모듈의 Column ID 와 Column 값이 하위 태그로 반복됩니다.",
        "데이터 태그는 'rowStatus' 를 마지막 하위 태그로 Row 의 상태값이 설정되며 'statusValue' 속성으로 상태코드값이 설정됩니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    scwin.btn_insertRow_onclick();
    scwin.btn_deleteRow_onclick();
    scwin.btn_setCellData_onclick();
    scwin.btn_removeRow_onclick();
}   



scwin.btn_insertRow_onclick = function (e) {
    let insertIndex = target1.insertRow();
    target1.setRowData(insertIndex,["insert1","insert2","insert3","insert4"],true);

    target1.deleteRow(insertIndex);

    insertIndex = target1.insertRow();
    target1.setRowData(insertIndex,["insert5","insert6","insert7","insert8"],true);

    target1.deleteRow(insertIndex);
};



scwin.btn_deleteRow_onclick = function (e) {
    target1.deleteRow(1);
};



scwin.btn_setCellData_onclick = function (e) {
    target1.setCellData(2, "col1", "change");
};



scwin.btn_removeRow_onclick = function (e) {
    target1.removeRow(3);
}



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})
    target1.setColumnFilter( {type:'row', colIndex:'col1', key:"insert5", condition:'or'})
};



scwin.btn_sort_onclick = function (e) {
    target1.sort("col1", 1);
};



scwin.btn_getVoidXML_onclick = function (e) {
    let onlyVoid = par_onlyVoid.getText();
    let rtn;

    if (onlyVoid == "true")
        rtn = target1.getVoidXML(true);
    else if (onlyVoid == "false")
        rtn = target1.getVoidXML(false);
    else
        rtn = target1.getVoidXML();
    const serializer = new XMLSerializer();
    let xmlString = serializer.serializeToString(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("result.xml: " + xmlString); 
};
